import json
from lib import *
R = J('r93')['trials']; s91 = J('r91')['a']; s95 = J('r95')['guard']; s77 = J('r77')['trials']
sy = [t for t in R if t['mode'] == 'sync']; pp = [t for t in R if t['mode'] == 'pipe']
tot_s = sum(t['acked'] for t in sy); tot_p = sum(t['acked'] for t in pp)
KV = lambda items, hl=(): {'items': items, 'hl': list(hl)}
def fl(nodes, cur=(), done=(), mark=()): return {'nodes': nodes, 'cur': list(cur), 'done': list(done), 'mark': list(mark)}
def bars(items, mx, cur=(), mark=(), done=()): return {'items': items, 'max': mx, 'cur': list(cur), 'mark': list(mark), 'done': list(done)}
steps = [
    step("Redis 复制是异步的:主库回复客户端时,这条写入可能还没到从库。主库随后崩溃、从库被提升,这些「已确认但未复制」的写入就丢了。问题是:窗口在哪里、多大?我把三类真实故障各测了一遍。", n=fl([['场景一', 'kill -9 主库'], ['场景二', '冻结再解冻旧主库'], ['场景三', 'sentinel 与主库分区,客户端仍写旧主库']], cur=[0, 1, 2]), kv=KV([['问题', '已确认的写入丢了多少']], ['问题'])),
    step(f"场景一:kill -9 主库(sentinel 完成切换)。同步逐条写:4 次共 {tot_s} 条写入被确认,新主库上丢失 0 条;管道 100 条一批:4 次共 {tot_p} 条,丢失 0 条。进程被杀时,已发出的数据还在操作系统缓冲区里,会被送到从库——所以这个场景基本不丢。", b=bars([['同步写:确认', tot_s / 1000, f'{tot_s} 条'], ['同步写:丢失', 0.3, '0'], ['管道:确认', tot_p / 1000, f'{tot_p} 条'], ['管道:丢失', 0.3, '0']], tot_p / 1000, done=[1, 3]), kv=KV([['kill -9', f'0 / {tot_s + tot_p}']], ['kill -9'])),
    step(f"场景二:冻结旧主库(SIGSTOP),从库升主后解冻(第 77 篇,集群):解冻后旧主库还以为自己是主库,一次立即发来的 SET 被回复 OK,随后被丢弃。3 次里 3 次都丢了这一条。窗口只有毫秒,但发生了。", n=fl([['旧主库(刚解冻)', '接受一次写入 → OK'], ['随后降为从库', '这条写入被丢弃']], mark=[0, 1]), kv=KV([['丢失', '3 / 3 次(各 1 条)']], ['丢失'])),
    step(f"场景三:sentinel 与主库分区,客户端 A 仍写旧主库(第 91 篇):{s91['okA']} 次写入被回复 OK,丢失 {s91['lost']} 条({s91['lost']/s91['okA']*100:.0f}%)。这是窗口最大的一种:旧主库在被降级之前一直在接受写入(那次约 {s91['demote']+s91['switch']+6:.0f} 秒)。", b=bars([['被回复 OK', s91['okA'], str(s91['okA'])], ['丢失', s91['lost'], str(s91['lost'])]], s91['okA'], mark=[1]), kv=KV([['脑裂', f"丢失 {s91['lost']} / {s91['okA']}"]], ['脑裂'])),
    step(f"缓解:旧主库配置 min-replicas-to-write 1、max-lag 3(第 94、95 篇):同样的脑裂实验里丢失降到 {s95['lost']} 条(被回复 OK 的 {s95['okA']} 条)。窗口缩小到 max-lag。", b=bars([['无保护:丢失', s91['lost'], str(s91['lost'])], ['min-replicas:丢失', s95['lost'], str(s95['lost'])]], s91['lost'], mark=[0], done=[1]), kv=KV([['丢失', f"{s91['lost']} → {s95['lost']}"]], ['丢失'])),
]
A = dict(
    n=93, series='redis', tags='Redis,Sentinel,数据丢失,真实验证,动画演示',
    desc=f'把故障转移里的写入丢失窗口在三类故障里量出来:kill -9 主库,{tot_s} 条同步写与 {tot_p} 条管道写共 8 次实验丢失 0 条;冻结再解冻的旧主库在解冻瞬间仍接受写入(3/3 次丢 1 条);sentinel 与主库分区、客户端继续写旧主库时,{s91["okA"]} 条被回复 OK 的写入丢了 {s91["lost"]} 条;加 min-replicas 后丢失降到 {s95["lost"]} 条。',
    lead='「Redis 故障转移会丢数据」这句话人人都说,但丢多少、什么时候丢,取决于故障的形态。这篇不复述结论,把三类故障各做一遍,数字并排放在一起:最常见的 kill -9 几乎不丢,而真正会丢的是「旧主库还活着、还有人在写它」的情形。',
    facts=[('kill -9:0 条', f'8 次实验、共 {tot_s + tot_p} 条已确认写入,新主库上无一丢失'), (f'脑裂:{s91["lost"]} / {s91["okA"]}', '旧主库在分区中继续被写、恢复后被降级时,已确认写入的丢失'), (f'{s95["lost"]} 条', '同样的脑裂加 min-replicas-to-write 1 / max-lag 3 之后的丢失')],
    body=[
        sec('场景一:kill -9 主库', '一主两从 + 3 个 sentinel(down-after 1000 ms);一个线程持续写主库并记录已确认的写入;kill 之后到新主库上逐条检查', term('', out('r93')),
            f'<p>同步逐条写(约每秒 2 万多条)与管道 100 条一批(每秒约 40 万条)各做 4 次:{tot_s + tot_p} 条已确认的写入,在新主库上<b>没有丢失一条</b>。原因我的解释是:进程被杀时,它已经写进套接字的数据还在内核里,会继续被送到从库(这是解释,没有单独验证);本机回环上从库也几乎没有复制延迟。真实网络里复制延迟大、或主机整体掉电时,这个结论不一定成立——本文没有覆盖。</p>'),
        sec('场景二、三:旧主库还活着', '', f'<p>会丢数据的是另一类:<b>旧主库并没有消失</b>。冻结后解冻(第 77 篇,集群里),解冻瞬间旧主库仍接受了一次写入并回复 OK,随后被丢弃(3 次里 3 次)。sentinel 与主库分区、客户端仍连着旧主库(第 91 篇):{s91["okA"]} 次写入被回复 OK,最终丢失 {s91["lost"]} 条({s91["lost"]/s91["okA"]*100:.0f}%),窗口是「旧主库仍接受写入」的整个时长。给旧主库加 <code>min-replicas-to-write 1</code>、<code>max-lag 3</code>(第 94、95 篇)后同一实验丢失 {s95["lost"]} 条。</p>'),
        sec('结论', '', '<p>丢失窗口的大小,不取决于「有没有故障转移」,而取决于<b>旧主库在被替换之后还能接受多久写入</b>。进程被杀:窗口约等于零;进程被冻住又醒来:毫秒级;网络分区、客户端仍连旧主库:等于整个分区时长;<code>min-replicas-to-write</code> 把窗口压到 max-lag。这些数字来自本机回环、单一拓扑,请当作「哪类故障风险最大」的相对判断,不是生产环境的预测值。</p>'),
        sec('分步演示:三类故障的丢失对比', '', demo('故障转移中的写入丢失窗口', [('n', 'flow', '场景'), ('b', 'bars', '数据'), ('kv', 'kv', '要点')], steps, '本步的对象')),
    ],
    refs=[ENV_R + '。场景一新做 8 次;场景二引用第 77 篇,场景三引用第 91、95 篇的数据', '没有验证:物理机断电、复制延迟很大时的 kill -9、AOF 设置对场景一的影响、Redis Cluster 下的 kill -9 丢失量(第 75 篇有 3 次 0 丢失的小样本)、客户端重试对「已确认」语义的影响'],
)
